    Bug 1755659 - Remove unused nsIDBFolderInfo::expiredMark and associated code. r=mkmelin


    Apparently this has never been used since it had been introduced in the last century.

    Differential Revision: https://phabricator.services.mozilla.com/D254977

diff --git a/mailnews/db/msgdb/public/nsDBFolderInfo.h b/mailnews/db/msgdb/public/nsDBFolderInfo.h
index aafb4a11477..3dc1f83105b 100644
--- a/mailnews/db/msgdb/public/nsDBFolderInfo.h
+++ b/mailnews/db/msgdb/public/nsDBFolderInfo.h
@@ -116,9 +116,6 @@ class nsDBFolderInfo : public nsIDBFolderInfo {
   int32_t m_totalPendingMessages;
   int32_t m_unreadPendingMessages;

-  // news only (for now)
-  nsMsgKey
-      m_expiredMark;  // Highest invalid article number in group - for expiring
   // the db folder info will have to know what db and row it belongs to, since
   // it is really just a wrapper around the singleton folder info row in the
   // mdb.
@@ -144,7 +141,6 @@ class nsDBFolderInfo : public nsIDBFolderInfo {
   mdb_token m_imapUidValidityColumnToken;
   mdb_token m_totalPendingMessagesColumnToken;
   mdb_token m_unreadPendingMessagesColumnToken;
-  mdb_token m_expiredMarkColumnToken;
   mdb_token m_versionColumnToken;
 };

diff --git a/mailnews/db/msgdb/public/nsIDBFolderInfo.idl b/mailnews/db/msgdb/public/nsIDBFolderInfo.idl
